    name: { de: "Zoo Aussig", hu: "Ústí nad Labem-i Állatkert", ro: "Grădina Zoologică Ústí nad Labem", en: "Ústí nad Labem Zoo"},
    image: "/poi-images/czechrepublic-usti-nad-labem-zoo-life-v2.webp",
